@@ -1,5 +1,47 @@
 package slugify

+import (
+	"fmt"
+	"strings"
+)
+
+const maxSlugLen = 48
+
 func Slugify(value string) (string, error) {
-	return value, nil
+	var b strings.Builder
+	pendingSep := false
+
+	for i := 0; i < len(value); i++ {
+		c := value[i]
+		switch {
+		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
+			if pendingSep && b.Len() > 0 {
+				b.WriteByte('-')
+			}
+			pendingSep = false
+			b.WriteByte(c)
+		case c >= 'A' && c <= 'Z':
+			if pendingSep && b.Len() > 0 {
+				b.WriteByte('-')
+			}
+			pendingSep = false
+			b.WriteByte(c - 'A' + 'a')
+		default:
+			pendingSep = true
+		}
+	}
+
+	slug := b.String()
+	if slug == "" {
+		return "", fmt.Errorf("slugify: value %q normalizes to an empty slug", value)
+	}
+
+	if len(slug) > maxSlugLen {
+		slug = slug[:maxSlugLen]
+		for len(slug) > 0 && slug[len(slug)-1] == '-' {
+			slug = slug[:len(slug)-1]
+		}
+	}
+
+	return slug, nil
 }
